import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { CalendarDays, Clock, CheckCircle2 } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { toast } from "@/hooks/use-toast";

const statusConfig: Record<string, { label: string; variant: "default" | "secondary" | "destructive" | "outline" }> = {
  pending: { label: "Pendente", variant: "outline" },
  accepted: { label: "Aceito", variant: "default" },
  completed: { label: "Concluído", variant: "secondary" },
  rejected: { label: "Rejeitado", variant: "destructive" },
  cancelled: { label: "Cancelado", variant: "destructive" },
};

export function ClientDashboard() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  const { data: bookings, isLoading } = useQuery({
    queryKey: ["client-bookings", user?.id],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("bookings")
        .select(`
          *,
          services(title, price_min, price_type),
          profiles!bookings_provider_id_fkey(full_name)
        `)
        .eq("client_id", user!.id)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data;
    },
    enabled: !!user,
  });

  const cancelBooking = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase
        .from("bookings")
        .update({ status: "cancelled" })
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["client-bookings", user?.id] });
      toast({ title: "Solicitação cancelada." });
    },
    onError: (err: Error) => {
      toast({ title: "Erro ao cancelar", description: err.message, variant: "destructive" });
    },
  });

  const stats = {
    total: bookings?.length ?? 0,
    pending: bookings?.filter((b) => b.status === "pending").length ?? 0,
    accepted: bookings?.filter((b) => b.status === "accepted").length ?? 0,
    completed: bookings?.filter((b) => b.status === "completed").length ?? 0,
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="grid gap-4 sm:grid-cols-4">
          {Array.from({ length: 4 }).map((_, i) => (
            <Skeleton key={i} className="h-24" />
          ))}
        </div>
        <Skeleton className="h-64" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* KPIs */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardContent className="flex items-center gap-4 p-6">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
              <CalendarDays className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-bold">{stats.total}</p>
              <p className="text-sm text-muted-foreground">Total</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-6">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-yellow-500/10">
              <Clock className="h-5 w-5 text-yellow-600" />
            </div>
            <div>
              <p className="text-2xl font-bold">{stats.pending}</p>
              <p className="text-sm text-muted-foreground">Pendentes</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-6">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
              <CheckCircle2 className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-bold">{stats.accepted}</p>
              <p className="text-sm text-muted-foreground">Em andamento</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-6">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-secondary/10">
              <CheckCircle2 className="h-5 w-5 text-secondary" />
            </div>
            <div>
              <p className="text-2xl font-bold">{stats.completed}</p>
              <p className="text-sm text-muted-foreground">Concluídos</p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Booking list */}
      <Card>
        <CardHeader>
          <CardTitle>Minhas Solicitações</CardTitle>
        </CardHeader>
        <CardContent>
          {!bookings || bookings.length === 0 ? (
            <p className="py-8 text-center text-muted-foreground">
              Você ainda não fez nenhuma solicitação.
            </p>
          ) : (
            <div className="space-y-4">
              {bookings.map((booking: any) => {
                const sc = statusConfig[booking.status] || statusConfig.pending;
                return (
                  <div
                    key={booking.id}
                    className="flex flex-col gap-3 rounded-lg border p-4 sm:flex-row sm:items-center sm:justify-between"
                  >
                    <div className="flex-1 space-y-1">
                      <p className="font-semibold">{booking.services?.title || "Serviço"}</p>
                      <p className="text-sm text-muted-foreground">
                        Prestador: {booking.profiles?.full_name || "—"}
                      </p>
                      {booking.message && (
                        <p className="text-sm text-muted-foreground line-clamp-1">{booking.message}</p>
                      )}
                    </div>
                    <div className="flex flex-wrap items-center gap-3">
                      {booking.scheduled_date && (
                        <span className="text-xs text-muted-foreground">
                          {format(new Date(booking.scheduled_date), "dd/MM/yyyy HH:mm", { locale: ptBR })}
                        </span>
                      )}
                      <Badge variant={sc.variant}>{sc.label}</Badge>
                      {booking.status === "pending" && (
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => {
                            if (confirm("Cancelar esta solicitação?")) cancelBooking.mutate(booking.id);
                          }}
                          disabled={cancelBooking.isPending}
                        >
                          Cancelar
                        </Button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { toast } from "@/hooks/use-toast";
import { Briefcase, CalendarDays, CheckCircle2, Star, TrendingUp, Clock } from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";
import { ServiceForm } from "./ServiceForm";

const statusConfig: Record<string, { label: string; variant: "default" | "secondary" | "destructive" | "outline" }> = {
  pending: { label: "Pendente", variant: "outline" },
  accepted: { label: "Aceito", variant: "default" },
  completed: { label: "Concluído", variant: "secondary" },
  rejected: { label: "Rejeitado", variant: "destructive" },
  cancelled: { label: "Cancelado", variant: "destructive" },
};

export function ProviderDashboard() {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const [showServiceForm, setShowServiceForm] = useState(false);
  const [editingService, setEditingService] = useState<any>(null);

  const { data: bookings, isLoading: loadingBookings } = useQuery({
    queryKey: ["provider-bookings", user?.id],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("bookings")
        .select(`
          *,
          services(title),
          profiles!bookings_client_id_fkey(full_name, email)
        `)
        .eq("provider_id", user!.id)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data;
    },
    enabled: !!user,
  });

  const { data: services, isLoading: loadingServices } = useQuery({
    queryKey: ["provider-services", user?.id],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("services")
        .select("*, categories(name)")
        .eq("provider_id", user!.id)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data;
    },
    enabled: !!user,
  });

  const serviceIds = services?.map((s) => s.id) ?? [];
  const { data: providerStats } = useQuery({
    queryKey: ["provider-stats", user?.id, serviceIds.length],
    queryFn: async () => {
      if (serviceIds.length === 0) return { avg: null as number | null };
      const { data, error } = await supabase
        .from("service_stats")
        .select("average_rating, review_count")
        .in("service_id", serviceIds);
      if (error) throw error;
      let weighted = 0;
      let total = 0;
      (data ?? []).forEach((row) => {
        const count = Number(row.review_count) || 0;
        const avg = Number(row.average_rating) || 0;
        weighted += count * avg;
        total += count;
      });
      return { avg: total > 0 ? weighted / total : null };
    },
    enabled: !!user && serviceIds.length > 0,
  });

  const updateBooking = useMutation({
    mutationFn: async ({ id, status }: { id: string; status: string }) => {
      const { error } = await supabase
        .from("bookings")
        .update({ status: status as any })
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["provider-bookings"] });
      toast({ title: "Status atualizado!" });
    },
    onError: (err: any) => {
      toast({ title: "Erro", description: err.message, variant: "destructive" });
    },
  });

  const deleteService = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from("services").delete().eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["provider-services"] });
      toast({ title: "Serviço removido!" });
    },
    onError: (err: any) => {
      toast({ title: "Erro", description: err.message, variant: "destructive" });
    },
  });

  const stats = {
    totalServices: services?.length ?? 0,
    totalBookings: bookings?.length ?? 0,
    pending: bookings?.filter((b) => b.status === "pending").length ?? 0,
    completed: bookings?.filter((b) => b.status === "completed").length ?? 0,
    avgRating: providerStats?.avg != null ? providerStats.avg.toFixed(1) : "—",
  };

  const isLoading = loadingBookings || loadingServices;

  if (isLoading) {
    return (
      <div className="space-y-6">
        <div className="grid gap-4 sm:grid-cols-5">
          {Array.from({ length: 5 }).map((_, i) => (
            <Skeleton key={i} className="h-24" />
          ))}
        </div>
        <Skeleton className="h-64" />
      </div>
    );
  }

  if (showServiceForm || editingService) {
    return (
      <ServiceForm
        service={editingService}
        onClose={() => {
          setShowServiceForm(false);
          setEditingService(null);
        }}
        onSaved={() => {
          queryClient.invalidateQueries({ queryKey: ["provider-services"] });
          setShowServiceForm(false);
          setEditingService(null);
        }}
      />
    );
  }

  return (
    <div className="space-y-6">
      {/* KPIs */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5">
        <Card>
          <CardContent className="flex items-center gap-4 p-6">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
              <Briefcase className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-bold">{stats.totalServices}</p>
              <p className="text-sm text-muted-foreground">Serviços</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-6">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
              <CalendarDays className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-bold">{stats.totalBookings}</p>
              <p className="text-sm text-muted-foreground">Solicitações</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-6">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-yellow-500/10">
              <Clock className="h-5 w-5 text-yellow-600" />
            </div>
            <div>
              <p className="text-2xl font-bold">{stats.pending}</p>
              <p className="text-sm text-muted-foreground">Pendentes</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-6">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-secondary/10">
              <CheckCircle2 className="h-5 w-5 text-secondary" />
            </div>
            <div>
              <p className="text-2xl font-bold">{stats.completed}</p>
              <p className="text-sm text-muted-foreground">Concluídos</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="flex items-center gap-4 p-6">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-yellow-500/10">
              <Star className="h-5 w-5 text-yellow-600" />
            </div>
            <div>
              <p className="text-2xl font-bold">{stats.avgRating}</p>
              <p className="text-sm text-muted-foreground">Avaliação</p>
            </div>
          </CardContent>
        </Card>
      </div>

      <Tabs defaultValue="bookings">
        <TabsList>
          <TabsTrigger value="bookings">Solicitações</TabsTrigger>
          <TabsTrigger value="services">Meus Serviços</TabsTrigger>
        </TabsList>

        {/* Bookings tab */}
        <TabsContent value="bookings" className="mt-4">
          <Card>
            <CardHeader>
              <CardTitle>Solicitações Recebidas</CardTitle>
            </CardHeader>
            <CardContent>
              {!bookings || bookings.length === 0 ? (
                <p className="py-8 text-center text-muted-foreground">Nenhuma solicitação recebida ainda.</p>
              ) : (
                <div className="space-y-4">
                  {bookings.map((booking: any) => {
                    const sc = statusConfig[booking.status] || statusConfig.pending;
                    return (
                      <div key={booking.id} className="rounded-lg border p-4 space-y-3">
                        <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                          <div className="space-y-1">
                            <p className="font-semibold">{booking.services?.title || "Serviço"}</p>
                            <p className="text-sm text-muted-foreground">
                              Cliente: {booking.profiles?.full_name || "—"} ({booking.profiles?.email || ""})
                            </p>
                            {booking.scheduled_date && (
                              <p className="text-xs text-muted-foreground">
                                Data: {format(new Date(booking.scheduled_date), "dd/MM/yyyy HH:mm", { locale: ptBR })}
                              </p>
                            )}
                          </div>
                          <Badge variant={sc.variant}>{sc.label}</Badge>
                        </div>
                        {booking.message && (
                          <p className="text-sm text-muted-foreground bg-muted/50 rounded-md p-3">{booking.message}</p>
                        )}
                        {booking.status === "pending" && (
                          <div className="flex gap-2">
                            <Button
                              size="sm"
                              onClick={() => updateBooking.mutate({ id: booking.id, status: "accepted" })}
                              disabled={updateBooking.isPending}
                            >
                              Aceitar
                            </Button>
                            <Button
                              size="sm"
                              variant="destructive"
                              onClick={() => updateBooking.mutate({ id: booking.id, status: "rejected" })}
                              disabled={updateBooking.isPending}
                            >
                              Rejeitar
                            </Button>
                          </div>
                        )}
                        {booking.status === "accepted" && (
                          <div className="flex gap-2">
                            <Button
                              size="sm"
                              variant="secondary"
                              onClick={() => updateBooking.mutate({ id: booking.id, status: "completed" })}
                              disabled={updateBooking.isPending}
                            >
                              Marcar como Concluído
                            </Button>
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => updateBooking.mutate({ id: booking.id, status: "cancelled" })}
                              disabled={updateBooking.isPending}
                            >
                              Cancelar
                            </Button>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Services tab */}
        <TabsContent value="services" className="mt-4">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>Meus Serviços</CardTitle>
              <Button size="sm" onClick={() => setShowServiceForm(true)}>
                + Novo Serviço
              </Button>
            </CardHeader>
            <CardContent>
              {!services || services.length === 0 ? (
                <p className="py-8 text-center text-muted-foreground">Nenhum serviço cadastrado.</p>
              ) : (
                <div className="space-y-4">
                  {services.map((service: any) => {
                    return (
                      <div key={service.id} className="flex flex-col gap-3 rounded-lg border p-4 sm:flex-row sm:items-center sm:justify-between">
                        <div className="space-y-1">
                          <div className="flex items-center gap-2">
                            <p className="font-semibold">{service.title}</p>
                            <Badge variant={service.is_active ? "default" : "outline"}>
                              {service.is_active ? "Ativo" : "Inativo"}
                            </Badge>
                          </div>
                          <p className="text-sm text-muted-foreground">{(service as any).categories?.name}</p>
                        </div>
                        <div className="flex gap-2">
                          <Button size="sm" variant="outline" onClick={() => setEditingService(service)}>
                            Editar
                          </Button>
                          <Button
                            size="sm"
                            variant="destructive"
                            onClick={() => {
                              if (confirm("Remover este serviço?")) deleteService.mutate(service.id);
                            }}
                          >
                            Remover
                          </Button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { toast } from "@/hooks/use-toast";
import { ArrowLeft } from "lucide-react";
import { serviceSchema } from "@/lib/schemas/service";

interface ServiceFormProps {
  service?: any;
  onClose: () => void;
  onSaved: () => void;
}

export function ServiceForm({ service, onClose, onSaved }: ServiceFormProps) {
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [form, setForm] = useState({
    title: service?.title || "",
    description: service?.description || "",
    category_id: service?.category_id || "",
    price_min: service?.price_min ?? 0,
    price_max: service?.price_max ?? null as number | null,
    price_type: service?.price_type || "fixed",
    location: service?.location || "",
    is_active: service?.is_active ?? true,
  });

  const { data: categories } = useQuery({
    queryKey: ["categories"],
    queryFn: async () => {
      const { data, error } = await supabase.from("categories").select("*").order("name");
      if (error) throw error;
      return data;
    },
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrors({});

    const result = serviceSchema.safeParse({
      ...form,
      price_min: Number(form.price_min),
      price_max: form.price_max ? Number(form.price_max) : null,
    });

    if (!result.success) {
      const fieldErrors: Record<string, string> = {};
      result.error.errors.forEach((err) => {
        if (err.path[0]) fieldErrors[String(err.path[0])] = err.message;
      });
      setErrors(fieldErrors);
      return;
    }

    setLoading(true);
    const payload = {
      title: result.data.title,
      description: result.data.description,
      category_id: result.data.category_id,
      price_min: result.data.price_min,
      price_max: result.data.price_max,
      price_type: result.data.price_type as "fixed" | "hourly" | "negotiable",
      location: result.data.location || "",
      is_active: result.data.is_active,
      provider_id: user!.id,
    };

    if (service) {
      const { error } = await supabase.from("services").update(payload).eq("id", service.id);
      setLoading(false);
      if (error) {
        toast({ title: "Erro", description: error.message, variant: "destructive" });
      } else {
        toast({ title: "Serviço atualizado!" });
        onSaved();
      }
    } else {
      const { error } = await supabase.from("services").insert([payload]);
      setLoading(false);
      if (error) {
        toast({ title: "Erro", description: error.message, variant: "destructive" });
      } else {
        toast({ title: "Serviço criado!" });
        onSaved();
      }
    }
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" onClick={onClose}>
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <CardTitle>{service ? "Editar Serviço" : "Novo Serviço"}</CardTitle>
        </div>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4 max-w-lg">
          <div className="space-y-2">
            <Label htmlFor="svc-title">Título</Label>
            <Input
              id="svc-title"
              value={form.title}
              onChange={(e) => setForm({ ...form, title: e.target.value })}
              placeholder="Ex: Limpeza Residencial Completa"
              aria-invalid={!!errors.title}
            />
            {errors.title && <p className="text-sm text-destructive">{errors.title}</p>}
          </div>

          <div className="space-y-2">
            <Label htmlFor="svc-desc">Descrição</Label>
            <Textarea
              id="svc-desc"
              value={form.description}
              onChange={(e) => setForm({ ...form, description: e.target.value })}
              rows={4}
              placeholder="Descreva o serviço em detalhes..."
              aria-invalid={!!errors.description}
            />
            {errors.description && <p className="text-sm text-destructive">{errors.description}</p>}
          </div>

          <div className="space-y-2">
            <Label>Categoria</Label>
            <Select value={form.category_id} onValueChange={(v) => setForm({ ...form, category_id: v })}>
              <SelectTrigger aria-invalid={!!errors.category_id}>
                <SelectValue placeholder="Selecione uma categoria" />
              </SelectTrigger>
              <SelectContent>
                {categories?.map((c) => (
                  <SelectItem key={c.id} value={c.id}>{c.name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
            {errors.category_id && <p className="text-sm text-destructive">{errors.category_id}</p>}
          </div>

          <div className="grid gap-4 sm:grid-cols-3">
            <div className="space-y-2">
              <Label>Tipo de preço</Label>
              <Select value={form.price_type} onValueChange={(v) => setForm({ ...form, price_type: v })}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="fixed">Fixo</SelectItem>
                  <SelectItem value="hourly">Por hora</SelectItem>
                  <SelectItem value="negotiable">A combinar</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="svc-pmin">Preço mínimo (R$)</Label>
              <Input
                id="svc-pmin"
                type="number"
                min={0}
                step={0.01}
                value={form.price_min}
                onChange={(e) => setForm({ ...form, price_min: Number(e.target.value) })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="svc-pmax">Preço máximo (R$)</Label>
              <Input
                id="svc-pmax"
                type="number"
                min={0}
                step={0.01}
                value={form.price_max ?? ""}
                onChange={(e) => setForm({ ...form, price_max: e.target.value ? Number(e.target.value) : null })}
                placeholder="Opcional"
                aria-invalid={!!errors.price_max}
              />
              {errors.price_max && <p className="text-sm text-destructive">{errors.price_max}</p>}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="svc-loc">Localização</Label>
            <Input
              id="svc-loc"
              value={form.location}
              onChange={(e) => setForm({ ...form, location: e.target.value })}
              placeholder="Ex: São Paulo, SP"
            />
          </div>

          <div className="flex items-center gap-3">
            <Switch
              id="svc-active"
              checked={form.is_active}
              onCheckedChange={(v) => setForm({ ...form, is_active: v })}
            />
            <Label htmlFor="svc-active">Serviço ativo</Label>
          </div>

          <div className="flex gap-3 pt-2">
            <Button type="submit" disabled={loading}>
              {loading ? "Salvando..." : service ? "Salvar Alterações" : "Criar Serviço"}
            </Button>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
          </div>
        </form>
      </CardContent>
    </Card>
  );
}

