import { useAuth } from "@/contexts/AuthContext";
import { BookingDialog } from "@/components/BookingDialog";
import { ReviewForm } from "@/components/ReviewForm";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

export default function ServiceDetail() {
  const { id } = useParams<{ id: string }>();
  const { user } = useAuth();

  const { data: service, isLoading } = useQuery({
    queryKey: ["service", id],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("services")
        .select("*, categories(name, icon)")
        .eq("id", id!)
        .single();
      if (error) throw error;

      const [{ data: statsData }, providerRow] = await Promise.all([
        supabase
          .from("service_stats")
          .select("average_rating, review_count")
          .eq("service_id", id!)
          .maybeSingle(),
        fetchPublicProfileById(data.provider_id),
      ]);

      return { ...data, stats: statsData, provider: providerRow };
    },
    enabled: !!id,
  });

  const { data: reviews } = useQuery({
    queryKey: ["reviews", id],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("reviews")
        .select("*")
        .eq("service_id", id!)
        .order("created_at", { ascending: false });
      if (error) throw error;

      const clientIds = Array.from(new Set((data ?? []).map((r) => r.client_id)));
      const clientMap: Record<string, { full_name: string | null; avatar_url: string | null }> = {};
      if (clientIds.length > 0) {
        const clientRows = await fetchPublicProfilesByIds(clientIds);
        clientRows.forEach((p: PublicProfileSummary) => {
          clientMap[p.id] = { full_name: p.full_name, avatar_url: p.avatar_url };
        });
      }
      return (data ?? []).map((r) => ({ ...r, client: clientMap[r.client_id] ?? null }));
    },
    enabled: !!id,
  });

  const { data: similar } = useQuery({
    queryKey: ["similar-services", service?.category_id, id],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("services")
        .select("*, categories(name)")
        .eq("category_id", service!.category_id)
        .eq("is_active", true)
        .neq("id", id!)
        .limit(3);
      if (error) throw error;

      const ids = (data ?? []).map((s) => s.id);
      const ratingByService: Record<string, number> = {};
      if (ids.length > 0) {
        const { data: statsRows } = await supabase
          .from("service_stats")
          .select("service_id, average_rating")
          .in("service_id", ids);
        (statsRows ?? []).forEach((row) => {
          ratingByService[row.service_id] = Number(row.average_rating) || 0;
        });
      }
      return (data ?? []).map((s) => ({ ...s, rating: ratingByService[s.id] ?? 0 }));
    },
    enabled: !!service?.category_id,
  });

  const formatPrice = (min: number, max: number | null, type: string) => {
    const fmt = (v: number) =>
      v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
    if (type === "negotiable") return "A combinar";
    if (max && max > min) return `${fmt(min)} - ${fmt(max)}`;
    return fmt(min);
  };

  if (isLoading) {
    return (
      <Layout>
        <div className="container mx-auto px-4 py-10">
          <Skeleton className="mb-4 h-8 w-1/3" />
          <Skeleton className="mb-2 h-6 w-2/3" />
          <Skeleton className="h-40 w-full" />
        </div>
      </Layout>
    );
  }

  if (!service) {
    return (
      <Layout>
        <div className="container mx-auto px-4 py-20 text-center">
          <p className="text-lg text-muted-foreground">Serviço não encontrado.</p>
          <Link to="/services" className="mt-4 inline-block">
            <Button variant="outline" className="gap-2"><ArrowLeft className="h-4 w-4" /> Voltar</Button>
          </Link>
        </div>
      </Layout>
    );
  }

  const rating = (service as any).stats?.average_rating ?? 0;
  const reviewCount = (service as any).stats?.review_count ?? 0;
  const provider = (service as any).provider;

  return (
    <Layout>
      <div className="container mx-auto px-4 py-10">
        <Link to="/services" className="mb-6 inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground">
          <ArrowLeft className="h-4 w-4" /> Voltar aos serviços
        </Link>

        <div className="grid gap-8 lg:grid-cols-3">
          {/* Main */}
          <div className="lg:col-span-2 space-y-6">
            <div>
              <Badge variant="secondary" className="mb-3">{(service as any).categories?.name}</Badge>
              <h1 className="text-3xl font-bold">{service.title}</h1>
              <div className="mt-3 flex flex-wrap items-center gap-4 text-sm text-muted-foreground">
                {rating > 0 && (
                  <span className="flex items-center gap-1">
                    <Star className="h-4 w-4 fill-yellow-400 text-yellow-400" />
                    <strong className="text-foreground">{Number(rating).toFixed(1)}</strong>
                    ({reviewCount} avaliações)
                  </span>
                )}
                {service.location && (
                  <span className="flex items-center gap-1">
                    <MapPin className="h-4 w-4" /> {service.location}
                  </span>
                )}
              </div>
            </div>

            <div className="rounded-xl border bg-card p-6">
              <h2 className="mb-3 text-lg font-semibold">Descrição</h2>
              <p className="whitespace-pre-line text-muted-foreground leading-relaxed">{service.description}</p>
            </div>

            {/* Reviews */}
            <div className="rounded-xl border bg-card p-6">
              <h2 className="mb-4 text-lg font-semibold">
                Avaliações {reviewCount > 0 && <span className="text-muted-foreground font-normal">({reviewCount})</span>}
              </h2>
              {!reviews || reviews.length === 0 ? (
                <p className="text-sm text-muted-foreground">Nenhuma avaliação ainda.</p>
              ) : (
                <div className="space-y-4">
                  {reviews.map((review: any) => (
                    <div key={review.id} className="border-b pb-4 last:border-0 last:pb-0">
                      <div className="flex items-center gap-3">
                        <div className="flex h-8 w-8 items-center justify-center rounded-full bg-muted">
                          <User className="h-4 w-4 text-muted-foreground" />
                        </div>
                        <div>
                          <p className="text-sm font-medium">{review.client?.full_name || "Cliente"}</p>
                          <div className="flex items-center gap-2">
                            <div className="flex">
                              {[1, 2, 3, 4, 5].map((s) => (
                                <Star
                                  key={s}
                                  className={`h-3 w-3 ${s <= review.rating ? "fill-yellow-400 text-yellow-400" : "text-border"}`}
                                />
                              ))}
                            </div>
                            <span className="text-xs text-muted-foreground">
                              {format(new Date(review.created_at), "dd MMM yyyy", { locale: ptBR })}
                            </span>
                          </div>
                        </div>
                      </div>
                      <p className="mt-2 text-sm text-muted-foreground">{review.comment}</p>
                    </div>
                  ))}
                </div>
              )}
              <ReviewForm serviceId={service.id} providerId={service.provider_id} />
            </div>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            <Card>
              <CardContent className="p-6">
                <p className="text-3xl font-bold text-primary">
                  {formatPrice(service.price_min, service.price_max, service.price_type)}
                </p>
                {service.price_type === "hourly" && (
                  <p className="text-sm text-muted-foreground">por hora</p>
                )}
                <div className="mt-6">
                  <BookingDialog
                    serviceId={service.id}
                    providerId={service.provider_id}
                    serviceTitle={service.title}
                  />
                </div>
              </CardContent>
            </Card>

            {/* Provider info */}
            <Card>
              <CardContent className="p-6">
                <h3 className="mb-3 text-sm font-semibold text-muted-foreground">Profissional</h3>
                <div className="flex items-center gap-3">
                  <div className="flex h-12 w-12 items-center justify-center rounded-full bg-primary/10">
                    <User className="h-6 w-6 text-primary" />
                  </div>
                  <div>
                    <p className="font-semibold">{provider?.full_name || "Profissional"}</p>
                    <p className="flex items-center gap-1 text-xs text-muted-foreground">
                      <Clock className="h-3 w-3" />
                      Membro desde {format(new Date(service.created_at), "MMM yyyy", { locale: ptBR })}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Similar */}
            {similar && similar.length > 0 && (
              <div>
                <h3 className="mb-3 text-sm font-semibold text-muted-foreground">Serviços Similares</h3>
                <div className="space-y-3">
                  {similar.map((s: any) => {
                    const sr = s.rating ?? 0;
                    return (
                      <Link key={s.id} to={`/services/${s.id}`}>
                        <Card className="transition-shadow hover:shadow-md">
                          <CardContent className="p-4">
                            <p className="font-medium text-sm">{s.title}</p>
                            {sr > 0 && (
                              <span className="flex items-center gap-1 text-xs text-muted-foreground mt-1">
                                <Star className="h-3 w-3 fill-yellow-400 text-yellow-400" />
                                {Number(sr).toFixed(1)}
                              </span>
                            )}
                          </CardContent>
                        </Card>
                      </Link>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </Layout>
  );
}

import { useState } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { fetchPublicProfilesByIds, type PublicProfileSummary } from "@/integrations/supabase/views";
import type { Database } from "@/integrations/supabase/types";
import { Layout } from "@/components/layout/Layout";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Search, Star, MapPin, SlidersHorizontal } from "lucide-react";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

const ITEMS_PER_PAGE = 12;

type SortOption = "recent" | "rating" | "popular";

export default function Services() {
  const [search, setSearch] = useState("");
  const [categoryId, setCategoryId] = useState<string>("all");
  const [sort, setSort] = useState<SortOption>("recent");
  const [page, setPage] = useState(0);

  const { data: categories } = useQuery({
    queryKey: ["categories"],
    queryFn: async () => {
      const { data, error } = await supabase.from("categories").select("*").order("name");
      if (error) throw error;
      return data;
    },
  });

  const { data: servicesData, isLoading } = useQuery({
    queryKey: ["services", search, categoryId, sort, page],
    queryFn: async () => {
      const from = page * ITEMS_PER_PAGE;
      const to = (page + 1) * ITEMS_PER_PAGE - 1;

      type ServiceRow = Database["public"]["Tables"]["services"]["Row"] & {
        categories: { name: string; icon: string } | null;
      };
      let services: ServiceRow[] = [];
      let total = 0;

      if (sort === "recent") {
        let query = supabase
          .from("services")
          .select("*, categories(name, icon)", { count: "exact" })
          .eq("is_active", true);

        if (search.trim()) query = query.ilike("title", `%${search.trim()}%`);
        if (categoryId !== "all") query = query.eq("category_id", categoryId);

        const { data, error, count } = await query
          .order("created_at", { ascending: false })
          .range(from, to);
        if (error) throw error;
        services = data ?? [];
        total = count ?? 0;
      } else {
        // sort by rating or popularity: rank via service_stats first so that
        // pagination respects global order, not page-local in-memory sort.
        const statsOrderColumn = sort === "rating" ? "average_rating" : "review_count";

        let candidates = supabase
          .from("services")
          .select("id", { count: "exact" })
          .eq("is_active", true);
        if (search.trim()) candidates = candidates.ilike("title", `%${search.trim()}%`);
        if (categoryId !== "all") candidates = candidates.eq("category_id", categoryId);

        const { data: candidateRows, count, error: candidatesError } = await candidates;
        if (candidatesError) throw candidatesError;
        total = count ?? 0;
        const candidateIds = (candidateRows ?? []).map((r) => r.id as string);
        if (candidateIds.length === 0) {
          return { services: [], total: 0 };
        }

        const { data: rankedStats, error: rankedError } = await supabase
          .from("service_stats")
          .select("service_id, average_rating, review_count")
          .in("service_id", candidateIds)
          .order(statsOrderColumn, { ascending: false, nullsFirst: false })
          .range(from, to);
        if (rankedError) throw rankedError;

        const orderedIds = (rankedStats ?? [])
          .map((r) => r.service_id as string | null)
          .filter((id): id is string => !!id);
        if (orderedIds.length === 0) {
          return { services: [], total };
        }

        const { data: servicesData, error: servicesError } = await supabase
          .from("services")
          .select("*, categories(name, icon)")
          .in("id", orderedIds);
        if (servicesError) throw servicesError;

        const byId = new Map((servicesData ?? []).map((s) => [s.id, s]));
        services = orderedIds
          .map((id) => byId.get(id))
          .filter((s): s is NonNullable<typeof s> => !!s);
      }

      const serviceIds = services.map((s) => s.id);
      const providerIds = Array.from(new Set(services.map((s) => s.provider_id)));

      const statsMap: Record<string, { average_rating: number; review_count: number }> = {};
      const providerMap: Record<string, { full_name: string | null; avatar_url: string | null }> = {};

      if (serviceIds.length > 0) {
        const { data: statsData } = await supabase
          .from("service_stats")
          .select("service_id, average_rating, review_count")
          .in("service_id", serviceIds);
        statsData?.forEach((s) => {
          if (s.service_id) {
            statsMap[s.service_id] = {
              average_rating: s.average_rating ?? 0,
              review_count: s.review_count ?? 0,
            };
          }
        });
      }

      if (providerIds.length > 0) {
        const providerRows = await fetchPublicProfilesByIds(providerIds);
        providerRows.forEach((p: PublicProfileSummary) => {
          providerMap[p.id] = { full_name: p.full_name, avatar_url: p.avatar_url };
        });
      }

      const enriched = services.map((s) => ({
        ...s,
        stats: statsMap[s.id] || null,
        provider: providerMap[s.provider_id] || null,
      }));

      return { services: enriched, total };
    },
  });

  const services = servicesData?.services ?? [];
  const totalPages = Math.ceil((servicesData?.total ?? 0) / ITEMS_PER_PAGE);

  const formatPrice = (min: number, max: number | null, type: string) => {
    const fmt = (v: number) =>
      v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
    if (type === "negotiable") return "A combinar";
    if (max && max > min) return `${fmt(min)} - ${fmt(max)}`;
    return fmt(min);
  };

  const priceLabel = (type: string) => {
    if (type === "hourly") return "/hora";
    if (type === "negotiable") return "";
    return "";
  };

  return (
    <Layout>
      <div className="container mx-auto px-4 py-10">
        <div className="mb-8">
          <h1 className="text-3xl font-bold">Serviços</h1>
          <p className="mt-1 text-muted-foreground">Encontre o profissional perfeito para você</p>
        </div>

        {/* Filters */}
        <div className="mb-8 flex flex-col gap-4 rounded-xl border bg-card p-4 sm:flex-row sm:items-center">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Buscar serviços..."
              value={search}
              onChange={(e) => { setSearch(e.target.value); setPage(0); }}
              className="pl-9"
              aria-label="Buscar serviços"
            />
          </div>
          <Select value={categoryId} onValueChange={(v) => { setCategoryId(v); setPage(0); }}>
            <SelectTrigger className="w-full sm:w-48" aria-label="Filtrar por categoria">
              <SlidersHorizontal className="mr-2 h-4 w-4" />
              <SelectValue placeholder="Categoria" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">Todas as categorias</SelectItem>
              {categories?.map((c) => (
                <SelectItem key={c.id} value={c.id}>{c.name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={sort} onValueChange={(v) => { setSort(v as SortOption); setPage(0); }}>
            <SelectTrigger className="w-full sm:w-44" aria-label="Ordenar por">
              <SelectValue placeholder="Ordenar" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="recent">Mais recentes</SelectItem>
              <SelectItem value="rating">Melhor avaliação</SelectItem>
              <SelectItem value="popular">Mais populares</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Grid */}
        {isLoading ? (
          <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {Array.from({ length: 6 }).map((_, i) => (
              <Card key={i}><CardContent className="p-6"><Skeleton className="mb-4 h-6 w-3/4" /><Skeleton className="mb-2 h-4 w-full" /><Skeleton className="h-4 w-1/2" /></CardContent></Card>
            ))}
          </div>
        ) : services.length === 0 ? (
          <div className="py-20 text-center">
            <p className="text-lg text-muted-foreground">Nenhum serviço encontrado.</p>
            <p className="mt-1 text-sm text-muted-foreground">Tente ajustar os filtros.</p>
          </div>
        ) : (
          <>
            <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
              {services.map((service: any) => {
                const rating = service.stats?.average_rating ?? 0;
                const reviewCount = service.stats?.review_count ?? 0;
                return (
                  <Link key={service.id} to={`/services/${service.id}`}>
                    <Card className="h-full transition-shadow hover:shadow-lg">
                      <CardContent className="flex h-full flex-col p-6">
                        <div className="mb-3 flex items-start justify-between gap-2">
                          <Badge variant="secondary" className="text-xs">
                            {service.categories?.name}
                          </Badge>
                          {rating > 0 && (
                            <div className="flex items-center gap-1 text-sm">
                              <Star className="h-4 w-4 fill-yellow-400 text-yellow-400" />
                              <span className="font-medium">{Number(rating).toFixed(1)}</span>
                              <span className="text-muted-foreground">({reviewCount})</span>
                            </div>
                          )}
                        </div>
                        <h3 className="mb-2 text-lg font-semibold leading-tight">{service.title}</h3>
                        <p className="mb-4 flex-1 text-sm text-muted-foreground line-clamp-2">
                          {service.description}
                        </p>
                        <div className="flex items-center justify-between border-t pt-4">
                          <span className="text-lg font-bold text-primary">
                            {formatPrice(service.price_min, service.price_max, service.price_type)}
                            <span className="text-xs font-normal text-muted-foreground">{priceLabel(service.price_type)}</span>
                          </span>
                          {service.location && (
                            <span className="flex items-center gap-1 text-xs text-muted-foreground">
                              <MapPin className="h-3 w-3" /> {service.location}
                            </span>
                          )}
                        </div>
                        <p className="mt-3 text-xs text-muted-foreground">
                          por {service.provider?.full_name || "Profissional"}
                        </p>
                      </CardContent>
                    </Card>
                  </Link>
                );
              })}
            </div>

            {/* Pagination */}
            {totalPages > 1 && (
              <div className="mt-10 flex items-center justify-center gap-2">
                <Button variant="outline" size="sm" disabled={page === 0} onClick={() => setPage(page - 1)}>
                  Anterior
                </Button>
                <span className="text-sm text-muted-foreground">
                  Página {page + 1} de {totalPages}
                </span>
                <Button variant="outline" size="sm" disabled={page >= totalPages - 1} onClick={() => setPage(page + 1)}>
                  Próxima
                </Button>
              </div>
            )}
          </>
        )}
      </div>
    </Layout>
  );
}

import type { ReactNode } from "react";
import { MemoryRouter } from "react-router-dom";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";

export function makeQueryClient() {
  return new QueryClient({
    defaultOptions: {
      queries: { retry: false, gcTime: 0, staleTime: 0 },
      mutations: { retry: false },
    },
  });
}

export function Providers({
  children,
  initialEntries = ["/"],
  client = makeQueryClient(),
}: {
  children: ReactNode;
  initialEntries?: string[];
  client?: QueryClient;
}) {
  return (
    <QueryClientProvider client={client}>
      <MemoryRouter initialEntries={initialEntries}>{children}</MemoryRouter>
    </QueryClientProvider>
  );
}

